      "about_noot_token_paragraph_1": "Токен NOOT — это служебный токен, предназначенный для использования исключительно в экосистеме NOOTTOOLS и, в частности, в качестве внутренней валюты в видеоигре NOOTBATTLE. Его запланированные функции включают в себя использование в качестве внутренней валюты, предоставление доступа к премиум-функциям, участие в рейтингах и турнирах, а также содействие взаимодействию с будущими разработками в экосистеме, разработанной",
