      "token_creator_landing_desc": "Erstellen Sie mit unserer exklusiven NFT-Mitgliedschaft unbegrenzt benutzerdefinierte Token. Setzen Sie unsere NFTs ein und genießen Sie 6 Monate lang völlig KOSTENLOSE Token-Erstellung auf Solana.",
