      "future_developments_interaction_desc": "Das NOOTTOOLS-Ökosystem wird mit neuen Integrationen und Modulen wachsen, für die möglicherweise NOOT-Tokens erforderlich sind.",
      "token_name_label": "Tokenname",
      "noot_token": "NOOT-Token",
      "noot_ecosystem_use_case": "NOOTTOOLS & NOOTBATTLE Ökosystem",
      "noottools_sl": "NOOTTOOLS, SL",
      "about_noot_token_paragraph_1": "Der NOOT-Token ist ein Utility-Token, der ausschließlich zur Verwendung innerhalb des NOOTTOOLS-Ökosystems und insbesondere als interne Währung im NOOTBATTLE-Videospiel entwickelt wurde. Zu den geplanten Funktionalitäten gehören die Funktion als interne Währung, der Zugriff auf Premium-Funktionen, die Teilnahme an Ranglisten und Turnieren sowie die Erleichterung der Interaktion mit zukünftigen Entwicklungen im von entwickelten Ökosystem",
      "noot_token_warning_desc": "Der NOOT-Token stellt kein Finanzinstrument dar. Es werden keinerlei Beteiligungen, Dividenden, Zinsen oder wirtschaftliche Rechte jeglicher Art gewährt. NOOTTOOLS, SL garantiert nicht, dass NOOT einen Geldwert hat oder haben wird. Sein Zweck ist ausschließlich nützlich und auf das NOOTTOOLS- und NOOTBATTLE-Ökosystem beschränkt.",
      "discover_planned_ways": "Entdecken Sie alle geplanten Möglichkeiten, NOOT-Tokens im NOOTTOOLS- und NOOTBATTLE-Ökosystem zu verwenden",
      "noot_integration_desc": "NOOT-Token sind so konzipiert, dass sie nahtlos in das gesamte NOOTTOOLS-Ökosystem integriert werden können, wobei NOOTBATTLE die primäre Gaming-Plattform ist und bei allen zukünftigen Entwicklungen Nutzen und Wert bietet.",
      "used_for_improvements": "Wird für Verbesserungen, Fertigkeiten und Charaktere in NOOTBATTLE verwendet",
      "access_tournaments_competitive": "Nehmen Sie an Turnieren teil und verbessern Sie Ihre Platzierungen im Wettbewerbsmodus",
      "unlock_advanced_features": "Schalten Sie erweiterte Funktionen in NOOTTOOLS und besondere Vorteile frei",
      "noot_token_developer_desc": "NOOTTOOLS, SL hat es sich zur Aufgabe gemacht, innovative Spielerlebnisse zu schaffen, die die Grenzen dessen erweitern, was im Web3-Gaming-Bereich möglich ist. Der NOOT-Token repräsentiert unser Engagement, Spielern einen sinnvollen Nutzen innerhalb des NOOTTOOLS- und NOOTBATTLE-Ökosystems zu bieten.",
      "noot_whitepaper_available_desc": "Detaillierte Informationen zu den Spezifikationen und der Roadmap des Tokens finden Sie im Whitepaper.",
