      "faq_q1": "Wie erstelle ich meinen ersten Token?",
      "faq_a1": "Schließen Sie einfach Ihr Wallet an, füllen Sie das Token-Erstellungsformular aus und stellen Sie es in der Solana-Blockchain bereit. Unsere intuitive Benutzeroberfläche führt Sie durch jeden Schritt.",
      "faq_q2": "Wie hoch sind die Gebühren für die Token-Erstellung?",
      "faq_a2": "Die Gebühren für die Token-Erstellung beginnen bei 0,05 SOL und beinhalten Bereitstellungskosten und Plattformgebühren. Für zusätzliche Funktionen wie Liquiditätspools können gesonderte Kosten anfallen.",
      "faq_q3": "Wie sicher ist die Plattform?",
      "faq_a3": "Wir verwenden Sicherheit auf Unternehmensniveau mit mehrschichtiger Verschlüsselung, intelligenten Vertragsprüfungen und regelmäßigen Sicherheitsupdates. Ihre Vermögenswerte werden durch branchenführende Sicherheitsmaßnahmen geschützt.",
      "faq_q4": "Kann ich eine Rückerstattung erhalten?",
      "faq_a4": "Aufgrund der Natur von Blockchain-Transaktionen sind die meisten Gebühren nicht erstattungsfähig. Wir bieten Ihnen jedoch die volle Unterstützung, um sicherzustellen, dass Ihr Projekt gelingt.",
