      "about_noot_token_paragraph_1": "NOOT トークンは、NOOTTOOLS エコシステム内でのみ使用されるように設計されたユーティリティ トークンであり、特に NOOTBATTLE ビデオ ゲームの内部通貨として使用されます。計画されている機能には、内部通貨としての機能、プレミアム機能へのアクセスの提供、ランキングやトーナメントへの参加の有効化、および開発されたエコシステムの将来の開発との相互作用の促進が含まれます。",
      "noot_token_warning_desc": "NOOT トークンは金融商品を構成しません。いかなる種類の参加、配当、利益、または経済的権利も付与しません。 NOOTTOOLS、SL は、NOOT が金銭的価値を持つこと、または今後持つであろうことを保証しません。その目的はもっぱら実用的なものであり、NOOTTOOLS および NOOTBATTLE エコシステムに限定されています。",
      "discover_planned_ways": "NOOTTOOLS および NOOTBATTLE エコシステム内で NOOT トークンを使用できる計画されたすべての方法を発見します。",
      "noot_integration_desc": "NOOT トークンは、NOOTTOOLS エコシステム全体にシームレスに統合されるように設計されており、NOOTBATTLE が主要なゲーム プラットフォームとなり、将来のすべての開発にわたって実用性と価値を提供します。",
      "used_for_improvements": "NOOTBATTLE内の改善、スキル、キャラクターに使用されます",
      "access_tournaments_competitive": "トーナメントにアクセスし、対戦モードでランキングを向上させます",
      "unlock_advanced_features": "NOOTTOOLS の高度な機能と特別な特典を利用できるようにする",
      "noot_token_developer_desc": "SL の NOOTTOOLS は、Web3 ゲーム空間で可能なことの限界を押し上げる革新的なゲーム体験の作成に取り組んでいます。 NOOT トークンは、NOOTTOOLS および NOOTBATTLE エコシステム内で有意義なユーティリティをプレイヤーに提供するという私たちの献身を表しています。",
      "noot_whitepaper_available_desc": "トークンの仕様とロードマップの詳細については、ホワイトペーパーをご覧ください。",
