      "about_noot_token_paragraph_1": "رمز NOOT هو رمز مميز مصمم للاستخدام فقط داخل نظام NOOTTOOLS البيئي، وعلى وجه الخصوص، كعملة داخلية في لعبة فيديو NOOTBATTLE. وتشمل وظائفها المخططة العمل كعملة داخلية، وتوفير الوصول إلى الميزات المميزة، وتمكين المشاركة في التصنيفات والبطولات، وتسهيل التفاعل مع التطورات المستقبلية في النظام البيئي الذي طورته",
      "noot_token_warning_desc": "لا يشكل رمز NOOT أداة مالية. ولا يمنح مشاركة أو أرباح أو فوائد أو حقوق اقتصادية من أي نوع. لا تضمن NOOTTOOLS, SL أن NOOT لها أو سيكون لها قيمة نقدية. الغرض منه نفعي حصريًا ويقتصر على النظام البيئي NOOTTOOLS وNOOTBATTLE.",
      "discover_planned_ways": "اكتشف جميع الطرق المخططة التي يمكنك من خلالها استخدام رموز NOOT ضمن النظام البيئي NOOTTOOLS وNOOTBATTLE",
