      "noottools_sl": "नॉटटूल्स, एसएल",
      "about_noot_token_paragraph_1": "NOOT टोकन एक उपयोगिता टोकन है जिसे केवल NOOTTOOLS पारिस्थितिकी तंत्र के भीतर और विशेष रूप से NOOTBATTLE वीडियो गेम में आंतरिक मुद्रा के रूप में उपयोग करने के लिए डिज़ाइन किया गया है। इसकी नियोजित कार्यक्षमताओं में आंतरिक मुद्रा के रूप में सेवा करना, प्रीमियम सुविधाओं तक पहुंच प्रदान करना, रैंकिंग और टूर्नामेंट में भागीदारी को सक्षम करना और द्वारा विकसित पारिस्थितिकी तंत्र में भविष्य के विकास के साथ बातचीत की सुविधा प्रदान करना शामिल है।",
      "noot_token_warning_desc": "NOOT टोकन एक वित्तीय साधन नहीं है। यह किसी भी प्रकार की भागीदारी, लाभांश, हित या आर्थिक अधिकार प्रदान नहीं करता है। नूटूल्स, एसएल यह गारंटी नहीं देता कि NOOT का कोई मौद्रिक मूल्य है या होगा। इसका उद्देश्य विशेष रूप से उपयोगितावादी है और नूटूल्स और नूटबैटल पारिस्थितिकी तंत्र तक सीमित है।",
      "discover_planned_ways": "उन सभी नियोजित तरीकों की खोज करें जिनसे आप NOOTTOOLS और NOOTBATTLE पारिस्थितिकी तंत्र के भीतर NOOT टोकन का उपयोग कर सकते हैं",
      "noot_integration_desc": "NOOT टोकन को संपूर्ण NOOTTOOLS पारिस्थितिकी तंत्र में निर्बाध रूप से एकीकृत करने के लिए डिज़ाइन किया गया है, जिसमें NOOTBATTLE प्राथमिक गेमिंग प्लेटफ़ॉर्म है, जो भविष्य के सभी विकासों में उपयोगिता और मूल्य प्रदान करता है।",
      "used_for_improvements": "NOOTBATTLE के भीतर सुधार, कौशल और पात्रों के लिए उपयोग किया जाता है",
      "access_tournaments_competitive": "टूर्नामेंटों तक पहुंचें और प्रतिस्पर्धी मोड में रैंकिंग में सुधार करें",
      "unlock_advanced_features": "NOOTTOOLS में उन्नत सुविधाएँ और विशेष लाभ अनलॉक करें",
      "noot_token_developer_desc": "NOOTTOOLS, SL नवीन गेमिंग अनुभव बनाने के लिए प्रतिबद्ध है जो Web3 गेमिंग स्पेस में जो संभव है उसकी सीमाओं को आगे बढ़ाता है। NOOT टोकन NOOTTOOLS और NOOTBATTLE पारिस्थितिकी तंत्र के भीतर खिलाड़ियों को सार्थक उपयोगिता प्रदान करने के लिए हमारे समर्पण का प्रतिनिधित्व करता है।",
