      "future_developments_interaction_desc": "NOOTTOOLS 생태계는 NOOT 토큰이 필요할 수 있는 새로운 통합 및 모듈을 통해 성장할 것입니다.",
      "token_name_label": "토큰 이름",
      "noot_token": "NOOT 토큰",
      "noot_ecosystem_use_case": "NOOTTOOLS 및 NOOTBATTLE 생태계",
      "noottools_sl": "누툴즈, SL",
      "about_noot_token_paragraph_1": "NOOT 토큰은 NOOTTOOLS 생태계 내에서만, 특히 NOOTBATTLE 비디오 게임의 내부 통화로 사용되도록 설계된 유틸리티 토큰입니다. 계획된 기능에는 내부 통화 역할, 프리미엄 기능에 대한 액세스 제공, 순위 및 토너먼트 참여 가능, 개발된 생태계의 향후 개발과의 상호 작용 촉진이 포함됩니다.",
      "noot_token_warning_desc": "NOOT 토큰은 금융 상품을 구성하지 않습니다. 어떠한 종류의 참여, 배당금, 이자 또는 경제적 권리도 부여하지 않습니다. NOOTTOOLS, SL은 NOOT가 금전적 가치를 갖거나 가질 것이라고 보장하지 않습니다. 그 목적은 전적으로 실용적이며 NOOTTOOLS 및 NOOTBATTLE 생태계로 제한됩니다.",
      "discover_planned_ways": "NOOTTOOLS 및 NOOTBATTLE 생태계 내에서 NOOT 토큰을 사용할 수 있는 모든 계획된 방법을 알아보세요.",
      "noot_integration_desc": "NOOT 토큰은 전체 NOOTTOOLS 생태계에 원활하게 통합되도록 설계되었으며 NOOTBATTLE은 기본 게임 플랫폼으로 향후 모든 개발 전반에 걸쳐 유용성과 가치를 제공합니다.",
      "used_for_improvements": "NOOTBATTLE 내에서 개선, 기술 및 캐릭터에 사용됩니다.",
      "access_tournaments_competitive": "경쟁 모드에서 토너먼트에 참여하고 순위를 높이세요",
      "unlock_advanced_features": "NOOTTOOLS의 고급 기능과 특별 혜택을 잠금 해제하세요",
      "noot_token_developer_desc": "NOOTTOOLS, SL은 Web3 게임 공간에서 가능한 것의 경계를 넓히는 혁신적인 게임 경험을 만들기 위해 최선을 다하고 있습니다. NOOT 토큰은 NOOTTOOLS 및 NOOTBATTLE 생태계 내에서 플레이어에게 의미 있는 유틸리티를 제공하려는 우리의 헌신을 나타냅니다.",
