      "about_noot_token_paragraph_1": "Token NOOT adalah token utilitas yang dirancang untuk digunakan hanya dalam ekosistem NOOTTOOLS dan, khususnya, sebagai mata uang internal dalam video game NOOTBATTLE. Fungsionalitas yang direncanakan termasuk berfungsi sebagai mata uang internal, menyediakan akses ke fitur-fitur premium, memungkinkan partisipasi dalam peringkat dan turnamen, dan memfasilitasi interaksi dengan perkembangan masa depan dalam ekosistem yang dikembangkan oleh",
      "noot_token_warning_desc": "Token NOOT bukan merupakan instrumen keuangan. Ia tidak memberikan partisipasi, dividen, kepentingan atau hak ekonomi apapun. NOOTTOOLS, SL tidak menjamin bahwa NOOT memiliki atau akan memiliki nilai moneter. Tujuannya secara eksklusif bersifat utilitarian dan terbatas pada ekosistem NOOTTOOLS dan NOOTBATTLE.",
